// generar_312_revisiones_editables_y_fix_normal.js
// CHIQUI Entre Señales — Revisiones corporales editables + fix "todo normal"
//
// Dos cosas:
//
// 1. BUG CORREGIDO: si en una revisión corporal marcabas zonas con
//    "algo distinto" pero guardabas con el botón "Guardar sin agregar
//    observación", la revisión quedaba registrada como 'normal' (perdía
//    los hallazgos). Ahora el RESULTADO depende de lo que marcaste, no
//    del botón: si hay al menos una zona "con algo distinto", se guarda
//    SIEMPRE como 'con observación', aunque no agregues nota. El botón
//    solo decide si además vas a crear una observación o no.
//
// 2. REVISIONES EDITABLES Y ELIMINABLES desde el historial en Salud:
//    · Cada revisión del historial ahora tiene un menú (⋮) con "Editar"
//      y "Eliminar".
//    · "Editar" abre la revisión con todos sus estados cargados; puedes
//      corregir zona por zona (Normal / Algo distinto), cambiar la nota
//      y guardar (hace update, no crea una nueva).
//    · "Eliminar" borra la revisión (con confirmación).
//
// Archivos:
//   · app/revision-corporal/page.tsx (fix del botón + modo edición)
//   · app/prevencion/page.tsx         (menú editar/eliminar en historial)
//
// No hay SQL.
//
// Uso:
//   node generar_312_revisiones_editables_y_fix_normal.js

const fs2 = require('fs')
const path = require('path')

const archivos = [
  {
    ruta: "app/revision-corporal/page.tsx",
    base64: ""
  },
  {
    ruta: "app/prevencion/page.tsx",
    base64: ""
  },
]

let errores = 0
for (const a of archivos) {
  try {
    const rutaCompleta = path.join(process.cwd(), a.ruta)
    fs2.mkdirSync(path.dirname(rutaCompleta), { recursive: true })
    const contenido = Buffer.from(a.base64, 'base64').toString('utf8')
    fs2.writeFileSync(rutaCompleta, contenido, 'utf8')
    console.log('OK: ' + a.ruta)
  } catch (e) {
    errores++
    console.error('ERROR escribiendo ' + a.ruta + ': ' + e.message)
  }
}

if (errores === 0) {
  console.log('\nListo. 2 archivos escritos. git add / commit / push.')
} else {
  console.error('\nTerminó con ' + errores + ' error(es). NO hagas push.')
  process.exit(1)
}
